files.content:
html {
  height: 100%;
}

body {
  display: grid;
  place-items: center;
  min-width: 360px;
  height: inherit;
  margin: 0;
  padding: 40px;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted.svg);
}

h1,
h2,
p,
ul,
li {
  margin: 0;
  padding: 0;
}

.card {
  background-color: #fff;

  position: relative;
}

.card__image {
  width: 100%;
}

.card__text {
  padding: 40px;
  font-weight: normal;
  font-size: 31px;
}

.card__image-container {
  position: relative;
}

.card__image-container::after {
  content: 'Мудрые и непонятные слова';
  position: absolute;
  top: 20px;
  left: 20px;
  background-color: #000;
  color: #fff;
  padding: 10px;
}
